def is_valid_port_range(s):
    pieces = s.split('-')
    if len(pieces) != 2:
        return False
    p1_str, p2_str = pieces
    for piece in (p1_str, p2_str):
        if not piece.isdigit():
            return False
        if len(piece) > 1 and piece[0] == '0':
            return False
    p1, p2 = int(p1_str), int(p2_str)
    if p1 > 65535 or p2 > 65535:
        return False
    return p1 <= p2

