def mask_phone_intl(phone):
    segments = phone.split('-')
    masked = [segments[0]]
    for seg in segments[1:-1]:
        masked.append('*' * len(seg))
    masked.append(segments[-1])
    return '-'.join(masked)

def wrap_bullet(text, width, bullet):
    prefix = bullet + ' '
    indent = ' ' * len(prefix)
    limit = width - len(prefix)
    words = text.split()
    lines = []
    current = ''
    for word in words:
        candidate = word if not current else current + ' ' + word
        if len(candidate) <= limit:
            current = candidate
        else:
            if current:
                lines.append(current)
            current = word
    if current:
        lines.append(current)
    result = []
    for i, line in enumerate(lines):
        result.append((prefix if i == 0 else indent) + line)
    return result

def total_seconds_between(t1, t2):
    def secs(t):
        h, m, s = (int(x) for x in t.split(':'))
        return h * 3600 + m * 60 + s
    delta = secs(t2) - secs(t1)
    if delta < 0:
        delta += 86400
    return delta

def dict_diff_labels(old, new):
