    for key, old_val in old.items():
        if key in new:
            new_val = new[key]
            if new_val > old_val:
                result[key] = "increased"
            elif new_val < old_val:
                result[key] = "decreased"
            else:
                result[key] = "same"
    return result

def group_anagrams(words):
    order = []
    groups = {}
    for w in words:
        key = tuple(sorted(w))
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(w)
    return [groups[k] for k in order]

