def pluralize_count(word, n):
    if n == 1:
        return f"{n} {word}"
    lower = word.lower()
    if lower[-2:] in ('ch', 'sh') or lower[-1] in ('s', 'x', 'z'):
        plural = word + 'es'
    elif lower.endswith('y') and len(word) > 1 and lower[-2] not in 'aeiou':
        plural = word[:-1] + 'ies'
    else:
        plural = word + 's'
    return f"{n} {plural}"

