def goldbach_pair(n):
    def is_prime(x):
        if x < 2:
            return False
        for i in range(2, int(x ** 0.5) + 1):
            if x % i == 0:
                return False
        return True
    p = 2
    while p <= n // 2:
        if is_prime(p) and is_prime(n - p):
            return (p, n - p)
        p += 1
    return None

